def main():
    if len(SERVICES) != 50:
        raise SystemExit(f"Expected exactly 50 service definitions; found {len(SERVICES)}.")

    keys = [(item["category"], item["name"]) for item in SERVICES]
    if len(set(keys)) != 50:
        raise SystemExit("Duplicate category/name targets found. No database changes made.")

    for item in SERVICES:
        required = ("category", "name", "description", "authority",
                    "eligibility", "documents", "steps", "official_source")
        missing = [field for field in required if not str(item.get(field) or "").strip()]
        if missing:
            raise SystemExit(
                f"Incomplete definition for {item.get('name')}: {', '.join(missing)}. "
                "No database changes made."
            )

    db = SessionLocal()
    try:
        matched = []
        missing_targets = []
        ambiguous_targets = []

        for item in SERVICES:
            rows = db.query(Service).filter(
                Service.category == item["category"],
                Service.name == item["name"],
            ).all()

            if len(rows) == 0:
                missing_targets.append(f'{item["category"]} | {item["name"]}')
            elif len(rows) > 1:
                ambiguous_targets.append(f'{item["category"]} | {item["name"]}')
            else:
                matched.append((rows[0], item))

        if missing_targets or ambiguous_targets:
            print("Preflight failed. No records were changed.")
            for value in missing_targets:
                print("MISSING:", value)
            for value in ambiguous_targets:
                print("AMBIGUOUS:", value)
            return

        previous_drafts = sum(1 for row, _ in matched if row.status != "published")
        already_published = len(matched) - previous_drafts

        reviewed_at = datetime.now(timezone.utc)
        for row, item in matched:
            for field in (
                "description", "authority", "eligibility",
                "documents", "steps", "official_source"
            ):
                setattr(row, field, item[field])
            row.status = "published"
            row.last_reviewed = reviewed_at

        db.commit()

        counts = {}
        for item in SERVICES:
            counts[item["category"]] = counts.get(item["category"], 0) + 1

        print("SANAD AUDIT BATCH 10 COMPLETE")
        print(f"Verified target records: {len(matched)}")
        print(f"Moved from non-published to published: {previous_drafts}")
        print(f"Already published and refreshed: {already_published}")
        print("By category:")
        for category, count in sorted(counts.items()):
            print(f"  {category}: {count}")
        print("Inserted: 0")
        print("Deleted: 0")
        print("Only the 50 exact target records were updated.")
        print("Note: case-dependent requirements and annual dates are explicitly referred to the current official notice/portal; no unsupported fees or dates were invented.")

    except Exception:
        db.rollback()
        raise
    finally:
        db.close()

if __name__ == "__main__":
    main()
